function makeBird(color){let g=new THREE.Group();scene.add(g);ball(.56,'#a8b7c7',0,0,0,g,.85,.8,1.25);ball(.36,color,0,.27,-.5,g);ball(.29,'#e4e5db',0,.51,-.6,g);box(.16,.12,.33,'#efbb54',0,.49,-.94,g);for(let s of [-1,1])ball(.055,'#223c48',s*.24,.57,-.7,g);box(.45,.12,.65,'#536b80',0,0,.62,g);let wings=[];for(let s of [-1,1]){let w=new THREE.Group();w.position.set(s*.35,0,0);g.add(w);box(1.1,.13,.65,color,s*.53,0,0,w);box(.25,.1,.55,'#4c657a',s*1.12,0,.1,w);wings.push(w)}let ring=new THREE.Mesh(new THREE.RingGeometry(.7,.8,32),new THREE.MeshBasicMaterial({color,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.y=.2;scene.add(ring);return{g,wings,ring,color,x:0,score:0,hits:0,shots:0,combo:0,lastHit:-10,cool:0}}
const players=[makeBird('#f47783'),makeBird('#6aafff')];players[1].g.visible=players[1].ring.visible=false;
let mode='intro',count=1,time=60,elapsed=0,speed=26,spawnIn=0,base=26,targets=[],drops=[],splats=[],keys=new Set(),best=0,sound=false,ctx;try{best=+localStorage.getItem('pigeonExpressBest')||0}catch{}$('best').textContent=best;
function beep(f){if(!sound)return;try{ctx ||=new(window.AudioContext||window.webkitAudioContext)();ctx.resume();let o=ctx.createOscillator(),v=ctx.createGain();o.frequency.setValueAtTime(f,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(f*.55,ctx.currentTime+.1);v.gain.setValueAtTime(.06,ctx.currentTime);v.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);o.connect(v).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.13)}catch{}}
function spawn(){let kind=Math.random()<.28?'Person':Math.random()<.35?'Motorcycle':'Car',g=new THREE.Group(),x=kind==='Person'?(Math.random()<.5?-1:1)*(9+Math.random()*2):[-5.3,0,5.3][Math.floor(Math.random()*3)];g.position.set(x,0,-43);scene.add(g);let points=50,rx=1.15,rz=2,height=1.3;if(kind==='Car'){let c=['#ee7180','#e9c553','#81c8c5','#c3b5ed','#f7e9d0'][Math.floor(Math.random()*5)];box(2.2,.8,4,c,0,.7,0,g);box(1.9,.65,2.1,c,0,1.35,0,g);box(1.75,.05,.7,'#446978',0,1.69,.65,g);box(1.75,.05,.5,'#446978',0,1.69,-.7,g);for(let a of [-1.1,1.1])for(let b of [-1.3,1.3])ball(.36,'#2e424a',a,.4,b,g,.55,1,1);for(let a of [-.7,.7])box(.45,.18,.05,'#fff0b2',a,.8,2.03,g)}else if(kind==='Motorcycle'){points=150;rx=.7;rz=1.2;height=1.5;for(let z of [-.9,.9])ball(.45,'#2e424a',0,.48,z,g,.45,1,1);box(.5,.5,1.65,'#eaa249',0,.75,0,g);box(.9,.1,.15,'#ced8d4',0,1.2,.7,g);ball(.33,'#e85468',0,1.42,-.1,g);box(.5,.65,.6,'#394e6a',0,1.08,-.4,g)}else{points=100;rx=.65;rz=.65;height=1.5;box(.55,.8,.4,'#e95c76',0,.95,0,g);ball(.3,'#dca578',0,1.65,0,g);for(let a of [-.18,.18])box(.18,.5,.22,'#37516c',a,.35,0,g)}targets.push({g,kind,points,rx,rz,height,hit:false,extra:kind==='Person'?0:kind==='Car'?4:8})}
const flight=.24,birdZ=13;function drop(i){let p=players[i];if(mode!=='playing'||i>=count||p.cool>0)return;p.cool=.3;p.shots++;let m=ball(.2,'#fff9eb',p.x,4.8,birdZ);drops.push({m,i,x:p.x,age:0});beep(220)}function float(t,x,z,color){let v=new THREE.Vector3(x,2,z).project(camera),el=document.createElement('div');el.className='float';el.style.color=color;el.textContent=t;el.style.left=(v.x*.5+.5)*innerWidth+'px';el.style.top=(-v.y*.5+.5)*innerHeight+'px';document.body.appendChild(el);setTimeout(()=>el.remove(),1000)}
