function start(){clear();time=60;elapsed=0;base=+$('pace').value;speed=base;spawnIn=0;players.forEach((p,i)=>{Object.assign(p,{x:count===1?0:i?3:-3,score:0,hits:0,shots:0,combo:0,lastHit:-10,cool:0});p.g.visible=p.ring.visible=i<count});mode='playing';$('overlay').classList.add('hidden');$('pause').textContent='Ⅱ';$('secondLabel').textContent=count===2?'P2 · BLUE':'BEST';$('p2help').hidden=count===1;hud()}
function hud(){$('score').textContent=players[0].score;$('best').textContent=count===2?players[1].score:best;$('time').textContent=Math.ceil(time);$('speed').textContent=Math.round(speed*5)+' km/h';$('charge').style.width=(1-players[0].cool/.3)*100+'%';$('ready').textContent=players[0].cool?'Reloading…':'Tap to drop';$('timerStat').classList.toggle('danger',time<11)}
