function step(dt,now){if(mode==='playing'){elapsed+=dt;time=Math.max(0,60-elapsed);speed=base+elapsed*.18;spawnIn-=dt;if(spawnIn<=0){spawn();spawnIn=.30+Math.random()*.25}for(let i=0;i<count;i++){let p=players[i],left=i?'arrowleft':'a',right=i?'arrowright':'d';let dir=(keys.has(right)?1:0)-(keys.has(left)?1:0);if(count===1)dir+=(keys.has('arrowright')?1:0)-(keys.has('arrowleft')?1:0);p.x=THREE.MathUtils.clamp(p.x+Math.sign(dir)*19*dt,-11.5,11.5);p.cool=Math.max(0,p.cool-dt);p.g.rotation.z=THREE.MathUtils.lerp(p.g.rotation.z,-dir*.22,.15)}for(let o of scenery){o.position.z+=speed*dt;if(o.position.z>43)o.position.z-=108}for(let i=targets.length-1;i>=0;i--){let t=targets[i];t.g.position.z+=(speed+t.extra)*dt;if(t.g.position.z>35){scene.remove(t.g);targets.splice(i,1)}}for(let i=drops.length-1;i>=0;i--){let d=drops[i];d.age+=dt;d.m.position.y=4.8*(1-Math.pow(d.age/flight,2));if(d.age>=flight){impact(d);scene.remove(d.m);drops.splice(i,1)}}for(let i=splats.length-1;i>=0;i--){splats[i].position.z+=speed*dt;if(splats[i].position.z>35){scene.remove(splats[i]);splats.splice(i,1)}}hud();if(time<=0)finish()}cue.position.z=birdZ-(speed+4)*flight;for(let i=0;i<count;i++){let p=players[i];p.g.position.set(p.x,5,birdZ);p.ring.position.x=p.x;p.ring.position.z=birdZ;if(mode!=='paused'){p.wings.forEach((w,j)=>w.rotation.z=Math.sin(now*.025+i)*.4*(j?1:-1));p.g.position.y+=Math.sin(now*.006)*.08}}}
